import { motion } from 'framer-motion';
import { Area, AreaChart, ResponsiveContainer, Tooltip, XAxis, YAxis, RadialBarChart, RadialBar, PolarAngleAxis } from 'recharts';
import { CandlestickChart, BarChart3 } from 'lucide-react';
import { useTheme } from '../../contexts/ThemeContext';

const COLORS = {
  up: '#60a5fa',
  down: '#fb7185',
  neutral: '#a78bfa',
};

function toNumber(value) {
  const normalized = String(value ?? '').replace(/,/g, '').trim();
  const num = Number(normalized);
  return Number.isFinite(num) ? num : 0;
}

function MetricCard({ title, children, glow = false }) {
  return (
    <motion.div
      whileHover={{ y: -2 }}
      className={`rounded-[22px] border bg-[var(--bg-surface)] p-4 transition ${
        glow ? 'border-cyan-400/20 shadow-[0_0_26px_rgba(59,130,246,0.08)]' : 'border-[var(--border-color)]'
      }`}
    >
      <div className="mb-3 text-xs font-semibold uppercase tracking-[0.18em] text-[var(--text-secondary)]">{title}</div>
      {children}
    </motion.div>
  );
}

function TrendChip({ trend, change }) {
  const numericChange = toNumber(change);
  const tone = trend === 'down' ? 'text-rose-600' : 'text-emerald-600';
  return <div className={`text-sm font-semibold ${tone}`}>{numericChange > 0 ? '+' : ''}{numericChange}%</div>;
}

function MiniSpark({ series = [], stroke = '#60a5fa' }) {
  return (
    <div className="h-16">
      <ResponsiveContainer width="100%" height="100%">
        <AreaChart data={series}>
          <defs>
            <linearGradient id={`g-${stroke.replace('#', '')}`} x1="0" x2="0" y1="0" y2="1">
              <stop offset="5%" stopColor={stroke} stopOpacity={0.5} />
              <stop offset="95%" stopColor={stroke} stopOpacity={0.04} />
            </linearGradient>
          </defs>
          <XAxis dataKey="t" hide />
          <YAxis hide />
          <Tooltip
            contentStyle={{
              background: 'var(--chart-tooltip-bg)',
              border: '1px solid var(--chart-tooltip-border)',
              borderRadius: 14,
              color: 'var(--chart-tooltip-text)',
            }}
          />
          <Area type="monotone" dataKey="v" stroke={stroke} strokeWidth={2} fill={`url(#g-${stroke.replace('#', '')})`} />
        </AreaChart>
      </ResponsiveContainer>
    </div>
  );
}

function NumberStack({ items, tone = 'emerald', stacked = false }) {
  return (
    <div className={`grid gap-2 ${stacked ? 'grid-cols-1' : 'grid-cols-3'}`}>
      {items.map((item) => (
        <div key={item.label} className="rounded-2xl border border-[var(--border-color)] bg-[var(--bg-surface)] px-3 py-2">
          <div className="text-[11px] text-[var(--text-secondary)]">{item.label}</div>
          <div className={`mt-1 text-lg font-bold ${tone === 'rose' ? 'text-rose-600' : tone === 'amber' ? 'text-amber-600' : 'text-[var(--text-primary)]'}`}>
            {item.value}
          </div>
        </div>
      ))}
    </div>
  );
}

export default function MarketOverview({ data, loading, stacked = false, className = '', sectorRankings = [] }) {
  const indices = data?.indices || [];
  const limitUp = data?.limit_up || {};
  const heat = data?.heat || {};

  const up = indices[0];
  const deep = indices[1];
  const growth = indices[2];
  const marketTradeDate = data?.trade_date || up?.trade_date || deep?.trade_date || growth?.trade_date;

  return (
    <motion.section
      id="market-panel"
      initial={{ opacity: 0, y: 12 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.35, delay: 0.05 }}
      className="glass-card rounded-[28px] p-5"
    >
      <div className="mb-4 flex items-center justify-between">
        <div>
          <div className="text-sm font-semibold uppercase tracking-[0.24em] text-cyan-600/80">Market Overview</div>
          <div className="mt-1 text-[18px] font-semibold text-[var(--text-primary)]">市场环境</div>
          <div className="mt-1 text-xs text-[var(--text-secondary)]">指数交易日: {marketTradeDate || '数据暂缺'}</div>
        </div>
        <div className="rounded-full border border-[var(--border-color)] bg-[var(--bg-surface)] px-3 py-1 text-xs font-semibold text-[var(--text-secondary)]">
          6 Card View
        </div>
      </div>

      {loading ? (
        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-3 overflow-x-auto">
          {[...Array(6)].map((_, index) => (
            <div key={index} className="h-[190px] animate-pulse rounded-[22px] bg-[var(--bg-surface)]" />
          ))}
        </div>
      ) : (
        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-3 overflow-x-auto pb-2">
          <MetricCard title="上证指数" glow>
            <div className="flex items-start justify-between gap-2">
              <div>
                <div className="text-2xl font-bold text-[var(--text-primary)]">{toNumber(up?.value).toLocaleString()}</div>
                <div className="mt-1 text-xs text-[var(--text-secondary)]">SHCOMP</div>
              </div>
              <TrendChip trend={up?.trend} change={Number(up?.change || 0)} />
            </div>
            <MiniSpark series={up?.series || []} stroke={COLORS.up} />
          </MetricCard>

          <MetricCard title="深证成指" glow>
            <div className="flex items-start justify-between gap-2">
              <div>
                <div className="text-2xl font-bold text-[var(--text-primary)]">{toNumber(deep?.value).toLocaleString()}</div>
                <div className="mt-1 text-xs text-[var(--text-secondary)]">SZCOMP</div>
              </div>
              <TrendChip trend={deep?.trend} change={Number(deep?.change || 0)} />
            </div>
            <MiniSpark series={deep?.series || []} stroke={COLORS.up} />
          </MetricCard>

          <MetricCard title="创业板指">
            <div className="flex items-start justify-between gap-2">
              <div>
                <div className="text-2xl font-bold text-[var(--text-primary)]">{toNumber(growth?.value).toLocaleString()}</div>
                <div className="mt-1 text-xs text-[var(--text-secondary)]">GEM</div>
              </div>
              <TrendChip trend={growth?.trend} change={Number(growth?.change || 0)} />
            </div>
            <MiniSpark series={growth?.series || []} stroke={COLORS.down} />
          </MetricCard>

              <MetricCard title="板块排行">
                <div className="space-y-1">
                  {sectorRankings.length > 0 ? sectorRankings.slice(0, 6).map((sector, idx) => (
                    <div key={idx} className="flex justify-between items-center py-1">
                      <span className="text-xs text-[var(--text-secondary)] truncate max-w-[80px]">{sector.name}</span>
                      <span className={`text-sm font-bold ${(sector.change || 0) >= 0 ? 'text-rose-400' : 'text-emerald-400'}`}>
                        {(sector.change || 0) >= 0 ? '+' : ''}{(sector.change || 0).toFixed(2)}%
                      </span>
                    </div>
                  )) : (
                    <div className="text-xs text-[var(--text-secondary)]">暂无数据</div>
                  )}
                </div>
              </MetricCard>

              <MetricCard title="涨停/炸板">
                <div className="space-y-1">
                  <div className="flex justify-between items-center py-1">
                    <span className="text-xs text-[var(--text-secondary)]">涨停</span>
                    <span className="text-sm font-bold text-rose-400">{limitUp.limit_up ?? 0}</span>
                  </div>
                  <div className="flex justify-between items-center py-1">
                    <span className="text-xs text-[var(--text-secondary)]">炸板</span>
                    <span className="text-sm font-bold text-amber-400">{limitUp.broken ?? 0}</span>
                  </div>
                  <div className="flex justify-between items-center py-1">
                    <span className="text-xs text-[var(--text-secondary)]">跌停</span>
                    <span className="text-sm font-bold text-emerald-400">{limitUp.limit_down ?? 0}</span>
                  </div>
                  <div className="flex justify-between items-center py-1 mt-2">
                    <span className="text-xs text-[var(--text-secondary)]">触板</span>
                    <span className="text-sm font-bold text-[var(--text-secondary)]">{limitUp.touch_limit ?? 0}</span>
                  </div>
                </div>
              </MetricCard>

          <MetricCard title="市场热度" glow>
            <div className="flex h-full flex-col justify-between">
              <div className="mx-auto h-24 w-full max-w-[160px]">
                <ResponsiveContainer width="100%" height="100%">
                  <RadialBarChart
                    innerRadius="72%"
                    outerRadius="100%"
                    startAngle={180}
                    endAngle={0}
                data={[{ name: 'heat', value: toNumber(heat.value) }]}
                  >
                    <PolarAngleAxis type="number" domain={[0, 100]} tick={false} />
                    <RadialBar dataKey="value" cornerRadius={18} fill="var(--accent-cyan)" background />
                  </RadialBarChart>
                </ResponsiveContainer>
              </div>
              <div className="text-center">
                <div className="text-3xl font-bold text-[var(--text-primary)]">{toNumber(heat.value)}</div>
                <div className="mt-1 text-xs text-[var(--text-secondary)]">{heat.label || 'neutral'}</div>
              </div>
            </div>
          </MetricCard>
        </div>
      )}
    </motion.section>
  );
}
